  [6947] = { "Ricopre un'arma con un veleno che dura $N1 min.\nOgni colpo ha una probabilità del $N2% di avvelenare il nemico, infliggendogli istantaneamente $N3 danni da natura. $N4 cariche.", 0x87fac2e2, "u" },
  [6948] = { "Ti riporta alla tua residenza. Parla con un locandiere in un'altra località per cambiare la tua residenza.", 0xf92eb2a9, "u" },
  [6949] = { "Ricopre un'arma con un veleno che dura $N1 min.\nOgni colpo ha una probabilità del $N2% di avvelenare il nemico, infliggendogli istantaneamente $N3 danni da natura. $N4 cariche.", 0xf235d067, "u" },
  [6950] = { "Ricopre un'arma con un veleno che dura $N1 min.\nOgni colpo ha una probabilità del $N2% di avvelenare il nemico, infliggendogli istantaneamente $N3 danni da natura. $N4 cariche.", 0x7a650e6f, "u" },
  [6951] = { "Ricopre un'arma con un veleno che dura $N1 min.\nOgni colpo ha una probabilità del $N2% di avvelenare il nemico, aumentandone il tempo di lancio del $N3% per $D1. $N5 cariche.", 0xda8ce359, "u" },
  [6953] = { "Incendia il bersaglio con le fiamme della ⟦Great Forge=Grande Forgia⟧, infliggendo $N1 danni da fuoco sacro. Infligge $N2 volte tanti danni agli elementali del fuoco e della terra.", 0x1fe0e4bc, "u" },
